--- a/src/owner-card.ts
+++ b/src/owner-card.ts
@@ -1,18 +1,38 @@
 import { db } from './db.ts'

 const cache = new Map<number, Owner>()

 export async function getOwner(id: number): Promise<Owner> {
   const hit = cache.get(id)
   if (hit) return hit

   const owner = await db.owners.byId(id)
   cache.set(id, owner)
   return owner
 }

+export async function renameOwner(id: number, fullName: string): Promise<void> {
+  await db.owners.update(id, { fullName })
+  cache.set(id, { ...cache.get(id)!, fullName })
+}
+
+export async function attachPhone(id: number, phone: string): Promise<void> {
+  await db.owners.update(id, { phone })
+}
+
+export async function deleteOwner(id: number): Promise<void> {
+  await db.owners.remove(id)
+  cache.delete(id)
+}
